// src/modules/projects/services/clientProjects.ts
init_db();
var defaultMilestones = [
  "Discovery / Scope Confirmation",
  "Implementation",
  "Review / QA",
  "Delivery"
];
async function createClientProjectFromBooking(prisma, bookingId, actorId) {
  const run = async (db2) => {
    const booking = await db2.orm.public.Booking.where({ id: bookingId }).include("client").include("clientProject").first();
    if (!booking) throw new Error("Booking not found");
    const existingProjects = booking.clientProject;
    if (existingProjects && existingProjects.length) return existingProjects[0];
    const ownerId = booking.assignedToId || actorId || null;
    const project = await db2.orm.public.ClientProject.create({
      id: newId(),
      updatedAt: ts(),
      bookingId: booking.id,
      clientId: booking.clientId,
      title: booking.title,
      description: booking.description || "",
      ownerId,
      startedAt: null,
      dueAt: null,
      deliveredAt: null,
      completedAt: null
    });
    for (const [index, title] of defaultMilestones.entries()) {
      await db2.orm.public.ProjectMilestone.create({
        id: newId(),
        updatedAt: ts(),
        projectId: project.id,
        title,
        description: null,
        sortOrder: index + 1,
        dueAt: null,
        completedAt: null
      });
    }
    await db2.orm.public.ProjectActivity.create({
      id: newId(),
      clientProjectId: project.id,
      portfolioProjectId: null,
      actorId: actorId || null,
      _type: "PROJECT_CREATED",
      message: `Project tracker created for ${booking.title}`,
      visibleToClient: true,
      meta: null
    });
    return db2.orm.public.ClientProject.where({ id: project.id }).include("projectMilestones", (m) => m.orderBy((x) => x.sortOrder.asc())).include("projectActivities", (a) => a.orderBy((x) => x.createdAt.desc())).include("owner", (o) => o.select("id", "firstName", "lastName", "publicTitle")).first();
  };
  if ("transaction" in prisma) {
    return prisma.transaction(async (tx) => run(tx));
  }
  return run(prisma);
}

