async function applyCustomerAction(prisma, booking, action, body) {
  return prisma.transaction(async (tx) => {
    let data = {};
    let eventType2 = BOOKING_EVENT_TYPES.PROGRESS_UPDATED;
    let title = action;
    const stage = customerActionStage(action, booking.currentStage);
    switch (action) {
      case "ACCEPT_QUOTATION":
        eventType2 = BOOKING_EVENT_TYPES.QUOTATION_ACCEPTED;
        title = "Quotation accepted";
        break;
      case "DECLINE_QUOTATION":
        eventType2 = BOOKING_EVENT_TYPES.QUOTATION_REJECTED;
        title = "Quotation declined";
        break;
      case "REQUEST_CHANGES":
        eventType2 = BOOKING_EVENT_TYPES.CHANGES_REQUESTED;
        title = "Changes requested";
        break;
      case "CONFIRM_DELIVERY":
        eventType2 = BOOKING_EVENT_TYPES.BOOKING_COMPLETED;
        title = "Delivery confirmed";
        break;
      default:
        eventType2 = BOOKING_EVENT_TYPES.PROGRESS_UPDATED;
    }
    data.currentStage = stage;
    const b = await tx.orm.public.Booking.where({ id: booking.id }).update(data);
    await logBookingEvent(tx, {
      bookingId: booking.id,
      type: eventType2,
      title,
      stage,
      status: b.status,
      visibility: EVENT_VISIBILITY.CUSTOMER,
      actorType: "client",
      actorId: booking.client.id
    });
    return prisma.orm.public.Booking.where({ id: booking.id }).include("bookingEvents", (e) => e.orderBy((e2) => e2.createdAt.asc())).include("client").include("files").include("payments").first();
  });
}

