    rpName: process.env.WEB_AUTHN_RP_NAME || "AngiSoft Admin",
    origins: (process.env.WEB_AUTHN_ORIGIN || (production ? "https://admin.angisoft.co.ke" : "http://localhost:5174")).split(",").map((value) => value.trim()).filter(Boolean)
