// src/modules/cms/routes/blogs.ts
var createSchema3 = z15.object({
  title: z15.string().min(1),
  slug: z15.string().min(1),
  content: z15.string().min(1),
  subtitle: z15.string().optional(),
  contentType: z15.string().optional(),
  mediaUrl: z15.string().optional(),
  transcript: z15.string().optional(),
  coverImage: z15.string().optional(),
  excerpt: z15.string().optional(),
  tags: z15.array(z15.string()).optional(),
  published: z15.boolean().optional(),
  categoryId: z15.string().optional(),
  featured: z15.boolean().optional(),
  visibilityType: z15.string().optional(),
  visibleUntil: z15.string().datetime().optional().nullable(),
  resourceLinks: z15.any().optional()
});
var updateSchema5 = createSchema3.partial();
function blogsRouter(prisma = db_default) {
  const router5 = Router19();
  const permCtx = (req) => req.user?.sub ? { employeeId: req.user.sub, systemRole: req.user.role } : null;
  const canReview = async (req) => {
    const ctx5 = permCtx(req);
    return ctx5 ? has(ctx5, "publications.review") : false;
  };
  const canAuthor = async (req) => {
    const ctx5 = permCtx(req);
    return ctx5 ? has(ctx5, "publications.create") : false;
  };
  router5.get("/", optionalAuth, async (req, res) => {
    try {
      if (await canReview(req)) {
        const posts2 = await blogService.list({});
        return res.json(posts2);
      }
      if (await canAuthor(req)) {
        const posts2 = await blogService.list({ where: { authorId: req.user?.sub } });
        return res.json(posts2);
      }
      const posts = await blogService.list({ where: { published: true } });
      res.json(posts);
    } catch (err) {
      res.status(500).json({ error: "Server error" });
    }
  });
  router5.get("/:id", optionalAuth, async (req, res) => {
    try {
      const post2 = await blogService.get(req.params.id, {});
      if (!post2) return res.status(404).json({ error: "Not found" });
      if (post2.published) return res.json(post2);
      if (await canReview(req)) return res.json(post2);
      if (await canAuthor(req) && post2.authorId === req.user?.sub) return res.json(post2);
      return res.status(404).json({ error: "Not found" });
    } catch (err) {
      res.status(500).json({ error: "Server error" });
    }
  });
  router5.post("/", requireAuth, requireAccess("publications.create", ["ADMIN", "MARKETING", "DEVELOPER"]), async (req, res) => {
    const parsed = createSchema3.safeParse(req.body);
    if (!parsed.success) return res.status(400).json({ error: parsed.error.issues });
    try {
      const data = parsed.data;
      const created = await blogService.create({
        ...data,
        authorId: req.user?.sub,
        publishedAt: data.published ? ts() : null
      }, req.user);
      res.status(201).json(created);
    } catch (err) {
      res.status(500).json({ error: "Server error" });
    }
  });
  router5.put("/:id", requireAuth, requirePermission("publications.update_own"), async (req, res) => {
    const parsed = updateSchema5.safeParse(req.body);
    if (!parsed.success) return res.status(400).json({ error: parsed.error.issues });
    try {
      const existing = await prisma.orm.public.BlogPost.where({ id: req.params.id }).first();
      if (!existing) return res.status(404).json({ error: "Not found" });
      const canManageAll2 = await canReview(req);
      if (!canManageAll2 && existing.authorId !== req.user?.sub) {
        return res.status(403).json({ error: "Not authorized" });
      }
      const data = parsed.data;
      const publishedAt = data.published && !existing.publishedAt ? ts() : existing.publishedAt;
      const updated = await blogService.update(req.params.id, {
        ...data,
        publishedAt
      }, req.user);
      res.json(updated);
    } catch (err) {
      res.status(500).json({ error: "Server error" });
    }
  });
  router5.delete("/:id", requireAuth, requirePermission("publications.update_own"), async (req, res) => {
    try {
      const existing = await prisma.orm.public.BlogPost.where({ id: req.params.id }).first();
      if (!existing) return res.status(404).json({ error: "Not found" });
      const canManageAll2 = await canReview(req);
      if (!canManageAll2 && existing.authorId !== req.user?.sub) {
        return res.status(403).json({ error: "Not authorized" });
      }
      await blogService.delete(req.params.id, req.user);
      res.json({ ok: true });
    } catch (err) {
      res.status(500).json({ error: "Server error" });
    }
  });
  return router5;
}

