// src/modules/cms/routes/testimonials.ts
init_db2();
init_db();
var createSchema4 = z16.object({
  name: z16.string().min(1),
  company: z16.string().optional(),
  role: z16.string().optional(),
  text: z16.string().min(10),
  rating: z16.coerce.number().min(1).max(5).optional(),
  imageUrl: z16.string().optional(),
  videoUrl: z16.string().optional(),
  location: z16.string().optional(),
  projectType: z16.string().optional(),
  productId: z16.string().optional(),
  confirmed: z16.boolean().optional(),
  featured: z16.boolean().optional()
});
var updateSchema6 = createSchema4.partial();
function testimonialsRouter(prisma = db_default) {
  const router5 = Router20();
  const permCtx = (req) => req.user?.sub ? { employeeId: req.user.sub, systemRole: req.user.role } : null;
  const canModerate = async (req, testimonialId, fallbackRoles) => {
    const ctx5 = permCtx(req);
    if (!ctx5) return false;
    if (await isDenied(ctx5, "reviews.moderate")) return false;
    if (await has(ctx5, "reviews.moderate")) return true;
    if (req.user?.role && fallbackRoles.includes(req.user.role)) return true;
    return (await checkAssigned(ctx5, "reviews.moderate_assigned", {
      type: "review",
      id: testimonialId
    })).allowed;
  };
  router5.get("/", optionalAuth, async (req, res) => {
    try {
      const ctx5 = permCtx(req);
      const includeAll = ctx5 ? await has(ctx5, "reviews.moderate") : false;
      const list = await testimonialsService.list({
        where: includeAll ? {} : { confirmed: true, rejected: false }
      });
      res.json(list);
    } catch (err) {
      res.status(500).json({ error: "Server error" });
    }
  });
  router5.get("/featured", async (req, res) => {
    const featured = await prisma.orm.public.Testimonial.where({ featured: true, confirmed: true, rejected: false }).orderBy((t) => t.createdAt.desc()).limit(10).all();
    res.json(featured);
  });
  router5.get("/:id", optionalAuth, async (req, res) => {
    try {
      const ctx5 = permCtx(req);
      const includeAll = ctx5 ? await has(ctx5, "reviews.moderate") : false;
      const testimonial = await testimonialsService.get(req.params.id, {
        where: includeAll ? { id: req.params.id } : { id: req.params.id, confirmed: true }
      });
      if (!testimonial) return res.status(404).json({ error: "Not found" });
      res.json(testimonial);
    } catch (err) {
      res.status(500).json({ error: "Server error" });
    }
  });
  router5.post("/", requireAuth, requireAccess("reviews.moderate", ["ADMIN", "MARKETING"]), async (req, res) => {
    const parsed = createSchema4.safeParse(req.body);
    if (!parsed.success) return res.status(400).json({ error: parsed.error.issues });
    try {
      const created = await testimonialsService.create(parsed.data, req.user);
      res.status(201).json(created);
    } catch (err) {
      res.status(500).json({ error: "Server error" });
    }
  });
  router5.put("/:id", requireAuth, async (req, res) => {
    const parsed = updateSchema6.safeParse(req.body);
    if (!parsed.success) return res.status(400).json({ error: parsed.error.issues });
    if (!await canModerate(req, req.params.id, ["ADMIN", "MARKETING"])) {
      return res.status(403).json({ error: "Not authorized" });
    }
    try {
      const updated = await testimonialsService.update(req.params.id, parsed.data, req.user);
      res.json(updated);
    } catch (err) {
      res.status(500).json({ error: "Server error" });
    }
  });
  router5.patch("/:id/feature", requireAuth, async (req, res) => {
    if (!await canModerate(req, req.params.id, ["ADMIN", "MARKETING"])) {
      return res.status(403).json({ error: "Not authorized" });
    }
    const testimonial = await prisma.orm.public.Testimonial.where({ id: req.params.id }).first();
    if (!testimonial) return res.status(404).json({ error: "Not found" });
    const updated = await prisma.orm.public.Testimonial.where({ id: req.params.id }).update({ featured: !testimonial.featured });
    res.json(updated);
  });
  router5.patch("/:id/approve", requireAuth, async (req, res) => {
    if (!await canModerate(req, req.params.id, ["ADMIN", "MARKETING"])) {
      return res.status(403).json({ error: "Not authorized" });
    }
    const updated = await prisma.orm.public.Testimonial.where({ id: req.params.id }).update({ confirmed: true, rejected: false, rejectionReason: null });
    res.json(updated);
  });
  router5.patch("/:id/reject", requireAuth, async (req, res) => {
    if (!await canModerate(req, req.params.id, ["ADMIN", "MARKETING"])) {
      return res.status(403).json({ error: "Not authorized" });
    }
    const { reason } = req.body;
    const updated = await prisma.orm.public.Testimonial.where({ id: req.params.id }).update({ confirmed: false, rejected: true, rejectionReason: reason || "Rejected by admin" });
    res.json(updated);
  });
  router5.patch("/:id/reply", requireAuth, async (req, res) => {
    if (!await canModerate(req, req.params.id, ["ADMIN", "MARKETING"])) {
      return res.status(403).json({ error: "Not authorized" });
    }
    const { reply } = req.body;
    if (!reply) return res.status(400).json({ error: "Reply required" });
    const updated = await prisma.orm.public.Testimonial.where({ id: req.params.id }).update({ adminReply: reply });
    res.json(updated);
  });
  router5.post("/:id/react", async (req, res) => {
    const { visitorKey } = req.body;
    if (!visitorKey) return res.status(400).json({ error: "Visitor key required" });
    try {
      const existing = await prisma.orm.public.ReviewReaction.where({ testimonialId: req.params.id, visitorKey }).first();
      if (existing) return res.json({ alreadyReacted: true });
      await prisma.orm.public.ReviewReaction.create({
        id: newId(),
        testimonialId: req.params.id,
        visitorKey
      });
      const plan = prisma.raw.sql`UPDATE "Testimonial" SET "helpfulCount" = "helpfulCount" + 1 WHERE "id" = ${req.params.id}`.affectedCount().build();
      await prisma.runtime().execute(plan);
      res.json({ ok: true });
    } catch (err) {
      res.status(500).json({ error: "Server error" });
    }
  });
  router5.delete("/:id", requireAuth, async (req, res) => {
    if (!await canModerate(req, req.params.id, ["ADMIN"])) {
      return res.status(403).json({ error: "Not authorized" });
    }
    try {
      await testimonialsService.delete(req.params.id, req.user);
      res.json({ ok: true });
    } catch (err) {
      res.status(500).json({ error: "Server error" });
    }
  });
  return router5;
}

