var updateSchema7 = createSchema5.partial();
function slugify(value) {
  return value.toLowerCase().trim().replace(/[^\w\s-]/g, "").replace(/\s+/g, "-").replace(/-+/g, "-");
}
function serviceCategoriesRouter(prisma = db_default) {
  const router5 = Router21();
  const permCtx = (req) => req.user?.sub ? { employeeId: req.user.sub, systemRole: req.user.role } : null;
  router5.get("/", optionalAuth, async (req, res) => {
    try {
      const ctx5 = permCtx(req);
      const includeAll = ctx5 ? await has(ctx5, "services.update") : false;
      const list = await serviceCategoriesService.list({
        where: includeAll ? {} : { published: true }
      });
      res.json(list);
    } catch (err) {
      res.status(500).json({ error: "Server error" });
    }
  });
  router5.get("/:id", optionalAuth, async (req, res) => {
    try {
      const ctx5 = permCtx(req);
      const includeAll = ctx5 ? await has(ctx5, "services.update") : false;
      const category = await serviceCategoriesService.get(req.params.id, {
        where: includeAll ? { id: req.params.id } : { id: req.params.id, published: true }
      });
      if (!category) return res.status(404).json({ error: "Not found" });
      res.json(category);
    } catch (err) {
      res.status(500).json({ error: "Server error" });
    }
  });
  router5.post("/", requireAuth, requireAccess("service_categories.create", ["ADMIN", "MARKETING"]), async (req, res) => {
    const parsed = createSchema5.safeParse(req.body);
    if (!parsed.success) return res.status(400).json({ error: parsed.error.issues });
    try {
      const data = parsed.data;
      const slug = data.slug && data.slug.trim() ? data.slug : slugify(data.name);
      const created = await serviceCategoriesService.create({
        ...data,
        slug,
        order: data.order ?? 0
      }, req.user);
      res.status(201).json(created);
    } catch (err) {
      res.status(500).json({ error: "Server error" });
    }
  });
  router5.put("/:id", requireAuth, requireAccess("service_categories.update", ["ADMIN", "MARKETING"]), async (req, res) => {
    const parsed = updateSchema7.safeParse(req.body);
    if (!parsed.success) return res.status(400).json({ error: parsed.error.issues });
    try {
      const existing = await prisma.orm.public.ServiceCategory.where({ id: req.params.id }).first();
      if (!existing) return res.status(404).json({ error: "Not found" });
      const data = parsed.data;
      const slug = data.slug && data.slug.trim() ? data.slug : data.name ? slugify(data.name) : void 0;
      const updated = await serviceCategoriesService.update(req.params.id, {
        ...data,
        ...slug ? { slug } : {}
      }, req.user);
      if (data.name && data.name !== existing.name) {
        await prisma.orm.public.Service.where((s) => or4(s.categoryId.eq(existing.id), s.category.eq(existing.name))).updateAndCount({ category: data.name });
      }
      res.json(updated);
    } catch (err) {
      res.status(500).json({ error: "Server error" });
    }
  });
  router5.delete("/:id", requireAuth, requireAccess("service_categories.delete", ["ADMIN", "MARKETING"]), async (req, res) => {
    try {
      await prisma.orm.public.Service.where({ categoryId: req.params.id }).updateAndCount({ categoryId: null });
      await serviceCategoriesService.delete(req.params.id, req.user);
      res.json({ ok: true });
    } catch (err) {
      res.status(500).json({ error: "Server error" });
    }
  });
  return router5;
}

// src/shared/utils/crud.ts
import { Router as Router22 } from "express";
function createCrudRouter({ modelName, createSchema: createSchema25, updateSchema: updateSchema24, listSelect, idKey = "id", controller }) {
  const router5 = Router22();
  router5.post("/", async (req, res) => {
    const parsed = createSchema25.safeParse(req.body);
    if (!parsed.success) return res.status(400).json({ error: parsed.error.issues });
    try {
      const created = await controller.create(parsed.data, req.user);
      res.status(201).json(created);
    } catch (err) {
      res.status(500).json({ error: "Server error" });
    }
  });
  router5.get("/", async (req, res) => {
    try {
      const list = await controller.list();
      res.json(list);
    } catch (err) {
      res.status(500).json({ error: "Server error" });
    }
  });
  router5.get(`/:${idKey}`, async (req, res) => {
    try {
      const one = await controller.get(req.params[idKey]);
      if (!one) return res.status(404).json({ error: "Not found" });
      res.json(one);
    } catch (err) {
      res.status(500).json({ error: "Server error" });
    }
  });
  router5.put(`/:${idKey}`, async (req, res) => {
    const parsed = updateSchema24.safeParse(req.body);
    if (!parsed.success) return res.status(400).json({ error: parsed.error.issues });
    try {
      const updated = await controller.update(req.params[idKey], parsed.data, req.user);
      res.json(updated);
    } catch (err) {
      res.status(500).json({ error: "Server error" });
    }
  });
  router5.delete(`/:${idKey}`, async (req, res) => {
    try {
      await controller.delete(req.params[idKey], req.user);
      res.json({ ok: true });
    } catch (err) {
      res.status(500).json({ error: "Server error" });
    }
  });
  return router5;
}

