import { z as z18 } from "zod";
var createSettingSchema = z18.object({
  key: z18.string().min(1).max(128).regex(/^[a-zA-Z][a-zA-Z0-9._-]*$/),
  value: z18.unknown()
}).strict();
var settingsService = {
  async create(req, res) {
    try {
      const parsed = createSettingSchema.safeParse(req.body);
      if (!parsed.success) return res.status(400).json({ error: "Validation failed", details: parsed.error.issues });
      const { key, value } = parsed.data;
      res.status(201).json({ key, value, message: "Settings would be persisted" });
    } catch (error) {
      captureException2(error);
      res.status(500).json({ error: "Failed to create setting" });
    }
  },
  async list(req, res) {
    try {
      const settings = {
        apiVersion: process.env.API_VERSION || "1.0.0",
        maintenanceMode: process.env.MAINTENANCE_MODE === "true",
        stripeEnabled: !!process.env.STRIPE_SECRET,
        queueType: "in-memory",
        // Using in-memory queue (can add Redis later)
        sentryEnabled: !!process.env.SENTRY_DSN
      };
      res.json({ data: settings });
    } catch (error) {
      captureException2(error);
      res.status(500).json({ error: "Failed to fetch settings" });
    }
  },
  async getById(req, res) {
    try {
      const { id } = req.params;
      res.json({ key: id, message: "Settings retrieved" });
    } catch (error) {
      captureException2(error);
      res.status(500).json({ error: "Failed to fetch setting" });
    }
  },
  async update(req, res) {
    try {
      const { id } = req.params;
      const { value } = req.body;
      console.log(`[AUDIT] Settings updated: ${id} by ${req.user?.email || "unknown"}`);
      res.json({ id, value, message: "Setting updated" });
    } catch (error) {
      captureException2(error);
      res.status(500).json({ error: "Failed to update setting" });
    }
  },
  async delete(req, res) {
    try {
      const { id } = req.params;
      console.log(`[AUDIT] Settings deleted: ${id} by ${req.user?.email || "unknown"}`);
      res.json({ message: "Setting deleted" });
    } catch (error) {
      captureException2(error);
      res.status(500).json({ error: "Failed to delete setting" });
    }
  }
};

