function siteRouter(prisma) {
  const router5 = Router36();
  const getSetting = async (key) => {
    const setting = await prisma.orm.public.Setting.where({ key }).first();
    return setting?.value ?? null;
  };
  const upsertSetting = async (key, value, req) => {
    const setting = await prisma.transaction(async (tx) => {
      const existing = await tx.orm.public.Setting.where({ key }).first();
      if (existing) {
        return tx.orm.public.Setting.where({ key }).update({ value });
      }
      return tx.orm.public.Setting.create({ key, value, updatedAt: ts() });
    });
    await prisma.orm.public.AuditLog.create({
      id: newId(),
      actorId: req.user?.sub ?? null,
      actorRole: req.user?.role ?? null,
      action: "site.update",
      entity: "Setting",
      entityId: key
    }).catch(() => void 0);
    return setting;
  };
  for (const section of SITE_SECTIONS) {
    router5.get(`/${section.slug}`, async (_req, res) => {
      try {
        res.json(await getSetting(section.key));
      } catch (err) {
        res.status(500).json({ error: "Server error" });
      }
    });
    router5.put(`/${section.slug}`, requireAuth, requireAccess(section.permission, [...section.roles]), async (req, res) => {
      try {
        const isLegalSection = section.key === LEGAL_SETTING_KEYS.privacy || section.key === LEGAL_SETTING_KEYS.terms;
        let value = req.body;
        if (isLegalSection) {
          const parsed = storedDocumentSchema.safeParse(req.body ?? {});
          if (!parsed.success) {
            return res.status(400).json({ error: "Validation failed", details: parsed.error.issues });
          }
          value = parsed.data;
        }
        const result = await upsertSetting(section.key, value, req);
        res.json(result.value);
      } catch (err) {
        res.status(500).json({ error: "Server error" });
      }
    });
  }
  router5.get("/all", async (_req, res) => {
    try {
      const entries = await Promise.all(
        SITE_SECTIONS.map(async (section) => [section.slug, await getSetting(section.key)])
      );
      res.json(Object.fromEntries(entries));
    } catch (err) {
      res.status(500).json({ error: "Server error" });
    }
  });
  return router5;
}

// src/modules/crm/routes/newsletter.ts
init_db();
import { Router as Router37 } from "express";
import { v4 as uuidv42 } from "uuid";
import { z as z29 } from "zod";
var subscribeSchema = z29.object({
  email: z29.string().email(),
  name: z29.string().optional()
});
var broadcastSchema = z29.object({
  subject: z29.string().min(1),
  html: z29.string().min(1),
  text: z29.string().optional()
});
function newsletterRouter(prisma) {
  const router5 = Router37();
  router5.post("/subscribe", publicFormLimiter, async (req, res) => {
    const parsed = subscribeSchema.safeParse(req.body);
    if (!parsed.success) return res.status(400).json({ error: parsed.error.issues });
    const { email, name } = parsed.data;
    const existing = await prisma.orm.public.Subscriber.where({ email }).first();
    if (existing && existing.confirmed && !existing.unsubscribedAt) {
      return res.json({ message: "You are already subscribed!" });
    }
    const confirmToken = uuidv42();
    const frontendUrl = process.env.FRONTEND_URL || "https://angisoft.co.ke";
    if (existing) {
      await prisma.orm.public.Subscriber.where({ email }).update({
        confirmToken,
        confirmed: false,
        unsubscribedAt: null,
        name: name || existing.name
      });
    } else {
      await prisma.orm.public.Subscriber.create({
        id: newId(),
        email,
        name: name ?? null,
        confirmToken,
        unsubToken: uuidv42()
      });
    }
    const confirmUrl = `${frontendUrl}/newsletter/confirm?token=${confirmToken}`;
    await sendMail({
      to: email,
      subject: "Confirm your subscription \u2014 AngiSoft Technologies",
      title: `Welcome${name ? `, ${escapeHtml(name)}` : ""} to AngiSoft updates`,
      eyebrow: "Newsletter Confirmation",
      preheader: "One click confirms your subscription.",
      footerNote: "You received this because you subscribed to AngiSoft updates.",
      cta: { label: "Confirm Subscription", url: confirmUrl },
      html: `
                <p style="margin:0 0 16px">Thank you for subscribing to AngiSoft Technologies updates.</p>
                <p style="margin:0 0 8px">Please confirm your subscription using the button below. You'll get product news, company updates and practical engineering notes \u2014 no noise.</p>
                <p style="margin:0;color:#64748B;font-size:13px">If you didn't subscribe, simply ignore this email.</p>`,
      purpose: "updates"
    });
    res.json({ message: "Confirmation email sent! Please check your inbox." });
  });
  router5.get("/confirm", async (req, res) => {
    const token = req.query.token;
    if (!token) return res.status(400).json({ error: "Missing token" });
    const subscriber = await prisma.orm.public.Subscriber.where({ confirmToken: token }).first();
    if (!subscriber) return res.status(404).json({ error: "Invalid or expired token" });
    await prisma.orm.public.Subscriber.where({ id: subscriber.id }).update({
      confirmed: true,
      confirmedAt: ts(),
      confirmToken: null
    });
    res.json({ message: "Subscription confirmed! You will receive our latest updates." });
  });
  router5.get("/unsubscribe", async (req, res) => {
    const token = req.query.token;
    if (!token) return res.status(400).json({ error: "Missing token" });
    const subscriber = await prisma.orm.public.Subscriber.where({ unsubToken: token }).first();
    if (!subscriber) return res.status(404).json({ error: "Invalid link" });
    await prisma.orm.public.Subscriber.where({ id: subscriber.id }).update({
      unsubscribedAt: ts()
    });
    res.json({ message: "You have been unsubscribed. Sorry to see you go!" });
  });
  router5.get("/subscribers", requireAuth, requireAccess("newsletters.view", ["ADMIN", "MARKETING"]), async (req, res) => {
    const subscribers = await prisma.orm.public.Subscriber.where({ confirmed: true }).where((s) => s.unsubscribedAt.isNull()).orderBy((s) => s.subscribedAt.desc()).all();
    res.json(subscribers);
  });
  router5.post("/broadcast", requireAuth, requireAccess("newsletters.send", ["ADMIN", "MARKETING"]), async (req, res) => {
    const parsed = broadcastSchema.safeParse(req.body);
    if (!parsed.success) return res.status(400).json({ error: parsed.error.issues });
    const { subject, html, text: text6 } = parsed.data;
    const frontendUrl = process.env.FRONTEND_URL || "https://angisoft.co.ke";
    const subscribers = await prisma.orm.public.Subscriber.where({ confirmed: true }).where((s) => s.unsubscribedAt.isNull()).all();
    let sent = 0;
    for (const sub of subscribers) {
      const unsubLink = `${frontendUrl}/newsletter/unsubscribe?token=${sub.unsubToken}`;
      try {
        await sendMail({
          to: sub.email,
          subject,
          html,
          text: text6,
          purpose: "updates",
          eyebrow: "AngiSoft Updates",
          footerNote: "You're receiving this because you subscribed to AngiSoft updates.",
          unsubscribeUrl: unsubLink
        });
        sent++;
      } catch (err) {
        console.warn(`Failed to send to ${sub.email}:`, err.message);
      }
    }
    await logAudit({
      action: "newsletter_broadcast",
      entity: "Subscriber",
      actorId: req.user.sub,
      actorRole: req.user.role,
      meta: { subject, recipientCount: sent }
    });
    res.json({ message: `Broadcast sent to ${sent} subscribers`, total: subscribers.length, sent });
  });
  return router5;
}

