// src/modules/crm/routes/renewals.ts
init_db();
import { Router as Router68 } from "express";
var RENEWAL_WINDOW_DAYS = Math.max(7, Number(process.env.RENEWAL_WINDOW_DAYS ?? 90));
var REMINDER_COOLDOWN_DAYS = Math.max(1, Number(process.env.RENEWAL_REMINDER_COOLDOWN_DAYS ?? 30));
var MAX_CLIENTS_SCANNED = 200;
var DAY_MS2 = 24 * 60 * 60 * 1e3;
async function computeClientHealth(prisma, client2, now) {
  const projects = await prisma.orm.public.ClientProject.where({ clientId: client2.id }).select("status", "completedAt", "deliveredAt", "updatedAt").all();
  const completed = projects.map((p) => p.completedAt ?? p.deliveredAt).filter(Boolean).sort().pop() ?? null;
  const openProjects = projects.filter((p) => !["COMPLETED", "CANCELLED", "DELIVERED"].includes(String(p.status))).length;
  const bookings = await prisma.orm.public.Booking.where({ clientId: client2.id }).select("status", "updatedAt").orderBy((b) => b.updatedAt.desc()).limit(50).all();
  const lastBookingAt = bookings[0]?.updatedAt ?? null;
  const activeBookings = bookings.filter((b) => !["COMPLETED", "CANCELLED", "REJECTED", "DELIVERED"].includes(String(b.status))).length;
  const invoices = await prisma.orm.public.Invoice.where({ clientId: client2.id }).select("status", "balanceDue", "dueAt", "currency").all();
  const openInvoices = invoices.filter((i) => !["paid", "void", "draft"].includes(String(i.status)));
  const outstandingBalance = openInvoices.reduce((sum, i) => sum + Number(i.balanceDue ?? 0), 0);
  const overdueInvoices = openInvoices.filter((i) => i.dueAt && new Date(i.dueAt).getTime() < now).length;
  const tickets = await prisma.orm.public.SupportTicket.where({ clientId: client2.id }).select("status").all();
  const openTickets = tickets.filter((t) => !["resolved", "closed"].includes(String(t.status).toLowerCase())).length;
  const lastActivityCandidates = [
    completed,
    lastBookingAt,
    ...projects.map((p) => p.updatedAt),
    ...bookings.map((b) => b.updatedAt),
    ...openInvoices.map((i) => i.dueAt)
  ].filter(Boolean).map((d) => new Date(d).getTime());
  const lastActivityMs = lastActivityCandidates.length ? Math.max(...lastActivityCandidates) : null;
  const daysSinceActivity = lastActivityMs ? Math.floor((now - lastActivityMs) / DAY_MS2) : null;
  const hasActiveWork = openProjects > 0 || activeBookings > 0;
  let health = "active";
  if (!hasActiveWork && daysSinceActivity !== null && daysSinceActivity >= RENEWAL_WINDOW_DAYS) {
    health = "renewal_due";
  } else if (openTickets > 0 || overdueInvoices > 0 || outstandingBalance > 0) {
    health = "at_risk";
  }
  return {
    clientId: client2.id,
    name: client2.name,
    email: client2.email,
    org: client2.org ?? null,
    lastProjectCompletedAt: completed,
    lastBookingAt,
    openProjects,
    openTickets,
    outstandingBalance,
    overdueInvoices,
    daysSinceActivity,
    health
  };
}
function renewalsRouter(prisma) {
  const router5 = Router68();
  router5.use(requireAuth);
  router5.get("/", requirePermission("client_projects.view_all"), async (_req, res) => {
    const clients = await prisma.orm.public.Client.orderBy((c) => c.createdAt.desc()).limit(MAX_CLIENTS_SCANNED).select("id", "name", "email", "org").all();
    const now = Date.now();
    const rows2 = [];
    for (const client2 of clients) {
      try {
        rows2.push(await computeClientHealth(prisma, client2, now));
      } catch (err) {
        console.error(`renewals: health computation failed for client ${client2.id}`, err);
      }
    }
    const order = { renewal_due: 0, at_risk: 1, active: 2 };
    rows2.sort((a, b) => order[a.health] - order[b.health] || (b.daysSinceActivity ?? -1) - (a.daysSinceActivity ?? -1));
    res.json({
      renewalWindowDays: RENEWAL_WINDOW_DAYS,
      reminderCooldownDays: REMINDER_COOLDOWN_DAYS,
      clients: rows2,
      summary: {
        renewal_due: rows2.filter((r) => r.health === "renewal_due").length,
        at_risk: rows2.filter((r) => r.health === "at_risk").length,
        active: rows2.filter((r) => r.health === "active").length
      }
    });
  });
  router5.post("/remind", requirePermission("client_projects.view_all"), async (req, res) => {
    try {
      const clientId = String(req.body?.clientId ?? "");
      if (!clientId) return res.status(400).json({ error: "clientId is required" });
      const client2 = await prisma.orm.public.Client.where({ id: clientId }).select("id", "name", "email").first();
      if (!client2) return res.status(404).json({ error: "Client not found" });
      const cutoff = ts(Date.now() - REMINDER_COOLDOWN_DAYS * DAY_MS2);
      const recent = await prisma.orm.public.Notification.where({ userId: clientId }).where({ userType: "client" }).where({ _type: "renewal" }).where((n) => n.createdAt.gt(cutoff)).limit(1).all();
      if (recent.length > 0) {
        return res.status(409).json({ error: `A renewal reminder was already sent within the last ${REMINDER_COOLDOWN_DAYS} days` });
      }
      await prisma.orm.public.Notification.create({
        id: newId(),
        userId: clientId,
        userType: "client",
        _type: "renewal",
        title: "Let\u2019s talk about what\u2019s next",
        message: `Hi ${client2.name || "there"} \u2014 it\u2019s been a while since your last project with AngiSoft. Reply to this portal message or contact us to plan your next engagement.`,
        link: "/portal",
        meta: { kind: "renewal", sentBy: req.user?.sub ?? null }
      });
      await logAudit({
        actorId: req.user?.sub ?? null,
        actorRole: req.user?.role ?? null,
        action: "renewal.reminder_sent",
        entity: "Client",
        entityId: clientId
      });
      res.json({ ok: true });
    } catch (err) {
      res.status(500).json({ error: "Server error" });
    }
  });
  return router5;
}

