// src/modules/identity/routes/employee-emails.ts
import { Router as Router103 } from "express";
import { z as z81 } from "zod";
var upsertSchema4 = z81.object({
  email: z81.string().email(),
  isPrimary: z81.boolean().optional(),
  verified: z81.boolean().optional(),
  source: z81.string().optional()
});
function employeeEmailsRouter(prisma) {
  const router5 = Router103();
  router5.use(requireAuth);
  router5.get("/:employeeId/emails", requireAccess("staff.view", ["ADMIN", "SUPER_ADMIN", "HR"]), async (req, res) => {
    const employeeId = req.params.employeeId;
    const emails = await prisma.orm.public.EmployeeEmail.where({ employeeId }).orderBy([(e) => e.isPrimary.desc(), (e) => e.createdAt.asc()]).all().catch(() => []);
    res.json({ emails });
  });
  router5.post("/:employeeId/emails", requireAccess("staff.update", ["ADMIN", "SUPER_ADMIN", "HR"]), async (req, res) => {
    const employeeId = req.params.employeeId;
    const body = upsertSchema4.parse(req.body);
    const email = normalizeEmail(body.email);
    const existing = await prisma.orm.public.Employee.where({ id: employeeId }).first();
    if (!existing) return res.status(404).json({ error: "Employee not found" });
    const row = await ensureEmployeeEmail(prisma, employeeId, email, { isPrimary: body.isPrimary, verified: body.verified ?? true, source: body.source ?? "admin" });
    if (body.isPrimary) {
      await prisma.orm.public.Employee.where({ id: employeeId }).update({ email }).catch(() => {
      });
    }
    await logAudit({ actorId: req.user?.sub, actorRole: req.user?.role, action: "employee.email.upsert", entity: "Employee", entityId: employeeId, meta: { email, isPrimary: Boolean(body.isPrimary) } });
    res.status(201).json({ email: row });
  });
  router5.delete("/:employeeId/emails/:emailId", requireAccess("staff.update", ["ADMIN", "SUPER_ADMIN", "HR"]), async (req, res) => {
    const { employeeId, emailId } = req.params;
    const row = await prisma.orm.public.EmployeeEmail.where({ id: emailId, employeeId }).first().catch(() => null);
    if (!row) return res.status(404).json({ error: "Not found" });
    if (row.isPrimary) return res.status(400).json({ error: "Cannot delete primary email; set another primary first" });
    await prisma.orm.public.EmployeeEmail.where({ id: emailId }).delete();
    await logAudit({ actorId: req.user?.sub, actorRole: req.user?.role, action: "employee.email.delete", entity: "Employee", entityId: employeeId, meta: { emailId } });
    res.json({ ok: true });
  });
  return router5;
}

